import { Mesh, PlaneGeometry, Group, MeshBasicNodeMaterial, Color } from 'three/webgpu';
import { texture, uv, mix, smoothstep, vec3, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const colors = config.intent?.visualSpec?.colors ?? { ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10' };

  const group = new Group();
  group.userData.handlers = {};

  const geom = new PlaneGeometry(2, 1.25);

  let mat;
  if (config.imageUrl) {
    mat = new MeshBasicNodeMaterial({ transparent: true });
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      mat.map = tex;
      mat.needsUpdate = true;
    });
  } else {
    mat = new MeshBasicNodeMaterial();
    const c1 = new THREE.Color(colors.surface || '#0b0b10');
    const c2 = new THREE.Color(colors.ink || '#16161d');
    mat.colorNode = mix(vec3(c1.r, c1.g, c1.b), vec3(c2.r, c2.g, c2.b), smoothstep(0, 1, uv().y));
  }

  const mesh = new Mesh(geom, mat);
  group.add(mesh);

  // Render text content from spec
  for (const item of items) {
    if (!item.text) continue;
    const fontSize = item.typography?.fontSize || 39;
    const color = item.role === 'headline' ? colors.paper : colors.paper;
    const textMesh = ctx.fontAtlas.createText(item.text, {
      fontSize: fontSize,
      color: color,
      align: 'left',
      maxWidthPx: 400,
      letterSpacingPx: 2
    });
    textMesh.position.set(-0.8, 0.25, 0.01);
    group.add(textMesh);
  }

  // Subtle backdrop gradient (engineered gradient surface)
  const backdropGeom = new PlaneGeometry(3.5, 2);
  const backdropMat = new MeshBasicNodeMaterial();
  const surf = new THREE.Color(colors.surface);
  const ink = new THREE.Color(colors.ink);
  backdropMat.colorNode = mix(vec3(surf.r, surf.g, surf.b), vec3(ink.r, ink.g, ink.b), smoothstep(0, 1, uv().y));
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.z = -0.1;
  group.add(backdrop);

  group.userData.cleanup = () => {
    geom.dispose();
    backdropGeom.dispose();
    if (mat.dispose) mat.dispose();
    if (backdropMat.dispose) backdropMat.dispose();
  };

  return group;
}
